import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;
    static final int MAX = 1 << 20;
    static int[][] p = new int[MAX][MAX];
    static int[] arrF = new int[MAX];
    static int[] arrG = new int[MAX];
    static int[][] M = new int[21][21];
    static int[] idx0 = new int[MAX];
    static int[] idx1 = new int[MAX];
    static int[] rev = new int[MAX];
    static int[] match = new int[21];
    static int[][] adj = new int[21][21];
    static int n;
    static List<Integer> partA = new ArrayList<>();
    static List<Integer> partB = new ArrayList<>();
    static int[][] pArray = new int[21][21];

    static int binPow(int base, int exp) {
        long res = 1;
        long b = base;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * b) % MOD;
            }
            b = (b * b) % MOD;
            exp >>= 1;
        }
        return (int) res;
    }

    static void process(int[] f, List<Integer> left, List<Integer> right, List<Integer> subgraph, int[] idx) {
        List<int[]> edges = new ArrayList<>();
        for (int x : left) {
            for (int y : right) {
                edges.add(new int[]{x, y});
            }
        }
        int sizeEdges = edges.size();
        int totalMasks = 1 << sizeEdges;
        for (int mask = 0; mask < totalMasks; mask++) {
            int prob = 1;
            for (int i = 0; i < sizeEdges; i++) {
                int[] edge = edges.get(i);
                if (((mask >> i) & 1) == 1) {
                    prob = (int) ((long) prob * p[edge[0]][edge[1]] % MOD);
                    adj[edge[0]][edge[1]] = 1;
                } else {
                    prob = (int) ((long) prob * (MOD + 1 - p[edge[0]][edge[1]]) % MOD);
                    adj[edge[0]][edge[1]] = 0;
                }
            }
            for (int g : subgraph) {
                List<Integer> perm = new ArrayList<>();
                List<Integer> indices = new ArrayList<>();
                for (int x : left) perm.add(x);
                for (int i = 0; i < n; i++) {
                    if (((g >> i) & 1) == 1) {
                        indices.add(i + n);
                    }
                }
                boolean found = false;
                do {
                    boolean valid = true;
                    for (int i = 0; i < perm.size(); i++) {
                        if (adj[perm.get(i)][indices.get(i)] == 0) {
                            valid = false;
                            break;
                        }
                    }
                    if (valid) {
                        found = true;
                        break;
                    }
                } while (nextPermutation(indices));
                if (found) {
                    int maskIdx = idx[g];
                    rev[mask] |= (1 << maskIdx);
                }
            }
            f[0] = (f[0] + prob) % MOD;
        }
    }

    static boolean nextPermutation(List<Integer> arr) {
        int i = arr.size() - 2;
        while (i >= 0 && arr.get(i) >= arr.get(i + 1))
            i--;
        if (i < 0)
            return false;
        int j = arr.size() - 1;
        while (arr.get(j) <= arr.get(i))
            j--;
        Collections.swap(arr, i, j);
        int left = i + 1;
        int right = arr.size() - 1;
        while (left < right) {
            Collections.swap(arr, left, right);
            left++;
            right--;
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        n = Integer.parseInt(br.readLine());
        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) {
                int val = Integer.parseInt(st.nextToken());
                p[i][j + n] = (int) ((long) val * binPow(100, MOD - 2) % MOD);
            }
        }

        if (n == 1) {
            System.out.println(p[0][n]);
            return;
        }

        int sizeA = n / 2;
        int sizeB = n - sizeA;

        int countA = 0, countB = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            if (Integer.bitCount(mask) == sizeA) {
                idx0[mask] = countA++;
                partA.add(mask);
            }
            if (Integer.bitCount(mask) == sizeB) {
                idx1[mask] = countB++;
                partB.add(mask);
            }
        }

        for (int i = 0; i < partB.size(); i++) {
            int mask = partB.get(i);
            for (int big_mask = 0; big_mask < (1 << countB); big_mask++) {
                if (((big_mask >> i) & 1) == 1) {
                    rev[big_mask] |= (1 << idx0[(1 << n) - 1 - mask]);
                }
            }
        }

        List<Integer> left1 = new ArrayList<>();
        List<Integer> left2 = new ArrayList<>();
        List<Integer> rightNodes = new ArrayList<>();
        for (int i = n; i < 2 * n; i++) {
            rightNodes.add(i);
        }
        for (int i = 0; i < sizeA; i++) left1.add(i);
        for (int i = sizeA; i < n; i++) left2.add(i);

        process(arrF, left1, rightNodes, partA, idx0);
        process(arrG, left2, rightNodes, partB, idx1);

        for (int i = 0; i < countA; i++) {
            for (int mask = 0; mask < (1 << countA); mask++) {
                if (((mask >> i) & 1) == 1) {
                    arrF[mask] = (arrF[mask] + arrF[mask ^ (1 << i)]) % MOD;
                }
            }
        }

        long totalAns = 0;
        for (int mask = 1; mask < (1 << countB); mask++) {
            int w = (1 - arrF[(1 << countA) - 1 - rev[mask]] + MOD) % MOD;
            totalAns = (totalAns + (long) w * arrG[mask]) % MOD;
        }

        System.out.println(totalAns);
    }
}
